# Completa la línea marcada y compruébala con py check.
def predecir(nodo, fila):
    while "hoja" not in nodo:
        if fila[nodo["f"]] <= nodo["t"]:
            nodo = nodo["izq"]
        else:
            nodo = nodo["izq"]   # ← cambia esta línea: si no, va a la derecha
    return nodo["hoja"]

arbol = {"f": 0, "t": 61.9, "izq": {"hoja": "apta"}, "der": {"hoja": "defectuosa"}}
print(predecir(arbol, [63.0, 5.0]))   # defectuosa
